  const handleExportBondData = () => {
    const filteredBonds = bondsList.filter(b => {
      const matchCat = bondExportCategory === 'ALL' || b.category === bondExportCategory;
      const matchSearch = b.title.toLowerCase().includes(bondExportSearch.toLowerCase()) ||
                          b.issuer.toLowerCase().includes(bondExportSearch.toLowerCase()) ||
                          b.id.toLowerCase().includes(bondExportSearch.toLowerCase());
      return matchCat && matchSearch;
    });

    let content = '';
    let mimeType = 'text/plain';
    let fileName = `sovereign_bonds_export_${new Date().toISOString().slice(0, 10)}`;

    if (bondExportFormat === 'JSON') {
      const exportedData = filteredBonds.map(b => {
        const obj: Record<string, any> = {};
        if (bondExportIncludeColumns.id) obj.id = b.id;
        if (bondExportIncludeColumns.title) obj.title = b.title;
        if (bondExportIncludeColumns.issuer) obj.issuer = b.issuer;
        if (bondExportIncludeColumns.category) obj.category = b.category;
        if (bondExportIncludeColumns.couponRate) obj.couponRateApr = `${b.couponRate}%`;
        if (bondExportIncludeColumns.payoutFrequency) obj.payoutFrequency = b.payoutFrequency;
        if (bondExportIncludeColumns.maturityYears) obj.maturityYears = b.maturityYears;
        if (bondExportIncludeColumns.minInvestment) obj.minInvestmentUsd = b.minInvestment;
        if (bondExportIncludeColumns.collateralBacking) obj.collateralBacking = b.collateralBacking;
        if (bondExportIncludeColumns.esgGrade) obj.esgGrade = b.esgGrade;
        if (bondExportIncludeColumns.rating) obj.creditRating = b.rating;
        if (bondExportIncludeColumns.carbonOffsetTonsPerK) obj.carbonOffsetTonsPerK = b.carbonOffsetTonsPerK;
        if (bondExportIncludeColumns.taxStatus) obj.taxStatus = b.taxStatus;
        return obj;
      });
      content = JSON.stringify({
        metadata: {
          title: 'High-Seas Sovereign Debt Treasury Bond Export',
          exportedAt: new Date().toISOString(),
          recordCount: exportedData.length,
          taxExemption: '100% Tax-Exempt under UNCLOS Article 87 International Waters Safe Harbor'
        },
        bonds: exportedData
      }, null, 2);
      mimeType = 'application/json';
      fileName += '.json';
    } else if (bondExportFormat === 'CSV' || bondExportFormat === 'TSV') {
      const delimiter = bondExportFormat === 'TSV' ? '\t' : ',';
      const headers: string[] = [];
      if (bondExportIncludeColumns.id) headers.push('Bond ID');
      if (bondExportIncludeColumns.title) headers.push('Title');
      if (bondExportIncludeColumns.issuer) headers.push('Issuer');
      if (bondExportIncludeColumns.category) headers.push('Category');
      if (bondExportIncludeColumns.couponRate) headers.push('Coupon Rate (% APR)');
      if (bondExportIncludeColumns.payoutFrequency) headers.push('Payout Frequency');
      if (bondExportIncludeColumns.maturityYears) headers.push('Maturity (Yrs)');
      if (bondExportIncludeColumns.minInvestment) headers.push('Min Investment ($)');
      if (bondExportIncludeColumns.collateralBacking) headers.push('Collateral Backing');
      if (bondExportIncludeColumns.esgGrade) headers.push('ESG Grade');
      if (bondExportIncludeColumns.rating) headers.push('Rating');
      if (bondExportIncludeColumns.carbonOffsetTonsPerK) headers.push('CO2 Offset (Tons/k)');
      if (bondExportIncludeColumns.taxStatus) headers.push('Tax Status');

      const rows = filteredBonds.map(b => {
        const row: string[] = [];
        if (bondExportIncludeColumns.id) row.push(`"${b.id}"`);
        if (bondExportIncludeColumns.title) row.push(`"${b.title}"`);
        if (bondExportIncludeColumns.issuer) row.push(`"${b.issuer}"`);
        if (bondExportIncludeColumns.category) row.push(`"${b.category}"`);
        if (bondExportIncludeColumns.couponRate) row.push(`${b.couponRate}`);
        if (bondExportIncludeColumns.payoutFrequency) row.push(`"${b.payoutFrequency}"`);
        if (bondExportIncludeColumns.maturityYears) row.push(`${b.maturityYears}`);
        if (bondExportIncludeColumns.minInvestment) row.push(`${b.minInvestment}`);
        if (bondExportIncludeColumns.collateralBacking) row.push(`"${b.collateralBacking}"`);
        if (bondExportIncludeColumns.esgGrade) row.push(`"${b.esgGrade}"`);
        if (bondExportIncludeColumns.rating) row.push(`"${b.rating}"`);
        if (bondExportIncludeColumns.carbonOffsetTonsPerK) row.push(`${b.carbonOffsetTonsPerK}`);
        if (bondExportIncludeColumns.taxStatus) row.push(`"${b.taxStatus}"`);
        return row.join(delimiter);
      });

      content = [headers.join(delimiter), ...rows].join('\n');
      mimeType = bondExportFormat === 'TSV' ? 'text/tab-separated-values' : 'text/csv';
      fileName += bondExportFormat === 'TSV' ? '.tsv' : '.csv';
    } else if (bondExportFormat === 'XML') {
      const xmlRows = filteredBonds.map(b => `
  <Bond>
    <ID>${b.id}</ID>
    <Title>${b.title}</Title>
    <Issuer>${b.issuer}</Issuer>
    <Category>${b.category}</Category>
    <CouponRate>${b.couponRate}</CouponRate>
    <PayoutFrequency>${b.payoutFrequency}</PayoutFrequency>
    <MaturityYears>${b.maturityYears}</MaturityYears>
    <MinInvestment>${b.minInvestment}</MinInvestment>
    <CollateralBacking>${b.collateralBacking}</CollateralBacking>
    <EsgGrade>${b.esgGrade}</EsgGrade>
    <Rating>${b.rating}</Rating>
    <CarbonOffsetTonsPerK>${b.carbonOffsetTonsPerK}</CarbonOffsetTonsPerK>
    <TaxStatus>${b.taxStatus}</TaxStatus>
  </Bond>`).join('');

      content = `<?xml version="1.0" encoding="UTF-8"?>\n<SovereignBondTreasuryExport date="${new Date().toISOString()}">\n${xmlRows}\n</SovereignBondTreasuryExport>`;
      mimeType = 'application/xml';
      fileName += '.xml';
    } else {
      content = `================================================================================\n` +
        `HIGH-SEAS SOVEREIGN MARITIME DEBT PROSPECTUS & TREASURY BOND REPORT\n` +
        `================================================================================\n\n` +
        `Export Date: ${new Date().toLocaleString()}\n` +
        `Total Instrument Count: ${filteredBonds.length}\n` +
        `Governing Authority: UNCLOS Article 87 International Waters Safe Harbor Jurisdiction\n` +
        `Tax Immunity Status: 0% Capital Gains & Tax-Free Coupon Interest\n\n` +
        `REGISTERED SOVEREIGN BONDS & DEBT INSTRUMENTS:\n` +
        `--------------------------------------------------------------------------------\n\n` +
        filteredBonds.map((b, i) =>
          `[${i + 1}] ${b.title} (${b.id})\n` +
          `    - Issuer: ${b.issuer}\n` +
          `    - Category: ${b.category}\n` +
          `    - Fixed Coupon Yield: ${b.couponRate}% APR (${b.payoutFrequency})\n` +
          `    - Maturity Term: ${b.maturityYears} Years\n` +
          `    - Minimum Investment: $${b.minInvestment.toLocaleString()} USD\n` +
          `    - Credit Rating & ESG: ${b.rating} | ESG Grade: ${b.esgGrade}\n` +
          `    - Collateral Backing: ${b.collateralBacking}\n` +
          `    - Tax Status: ${b.taxStatus}\n` +
          `    - Description: ${b.description}\n`
        ).join('\n--------------------------------------------------------------------------------\n\n');
      mimeType = 'text/plain';
      fileName += '.txt';
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    triggerToast(`Exported ${filteredBonds.length} Sovereign Bonds as ${bondExportFormat} (${fileName})!`);
  };

